<?php declare(strict_types=1);$types=$catalogue['types']??[];$events=$catalogue['events']??[]; ?>
<section class="section"><div class="container-wide"><div class="section-heading"><p class="eyebrow">Restricted administration</p><h1>Event management</h1></div><?php if($message):?><div class="notice" role="status"><?= $e($message) ?></div><?php endif;?><?php if($error):?><div class="form-error" role="alert"><?= $e($error) ?></div><?php endif;?><details class="admin-panel"><summary>Create event</summary><form method="post" action="/admin/events" class="form-grid"><?php $event=[];$submit='Create event';include __DIR__.'/form.php';?></form></details><h2>Events</h2><?php foreach($events as $event):?><details class="admin-panel"><summary><?= $e($event['event_date'].' — '.$event['title'].' ('.$event['status'].')') ?></summary><p><a href="/admin/events/<?= rawurlencode($event['public_id']) ?>/attendees">Manage <?= $e($event['registration_count']) ?> attendees</a></p><form method="post" action="/admin/events/<?= rawurlencode($event['public_id']) ?>" class="form-grid"><?php $submit='Save event';include __DIR__.'/form.php';?></form><?php if($event['status']!=='cancelled'):?><form method="post" action="/admin/events/<?= rawurlencode($event['public_id']) ?>/cancel"><?= $csrf->field() ?><button class="btn btn-outline" type="submit">Cancel event</button></form><?php endif;?></details><?php endforeach;?></div></section>
